// $ pulumi import gcp:vertex/aiPipelineJob:AiPipelineJob default projects/{{project}}/locations/{{region}}/pipelineJobs/{{name}}
// $ pulumi import gcp:vertex/aiPipelineJob:AiPipelineJob default {{project}}/{{region}}/{{name}}
